import datetime

from ta_moler.events.fzmconsole.genericfzmconsole_lineevent import GenericFZMConsoleLineEvent


class SiteStateChangedToOnAir(GenericFZMConsoleLineEvent):
    """Sitestatechangedtoonair event class."""

    _re_detect_pattern = r'State changed to OnAir|Site goes On Air'

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for 'state changed to onair'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        """
        super(SiteStateChangedToOnAir, self).__init__(connection=connection, runner=runner,
                                                      till_occurs_times=till_occurs_times,
                                                      detect_patterns=[SiteStateChangedToOnAir._re_detect_pattern],
                                                      match='any')


